import{_ as s,C as r,c as l,o as g,ag as o,j as e,G as n,a as i}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"EasyCart Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/easycart-integration-with-fluentaffiliate.md","filePath":"guide/integrations/easycart-integration-with-fluentaffiliate.md","lastUpdated":1750922643000}'),u={name:"guide/integrations/easycart-integration-with-fluentaffiliate.md"};function f(c,t,p,d,h,m){const a=r("ZoomableImage");return g(),l("div",null,[t[0]||(t[0]=o('<h1 id="easycart-integration-with-fluentaffiliate" tabindex="-1">EasyCart Integration with FluentAffiliate <a class="header-anchor" href="#easycart-integration-with-fluentaffiliate" aria-label="Permalink to &quot;EasyCart Integration with FluentAffiliate&quot;">​</a></h1><p>EasyCart is a powerful e-commerce store and shopping cart builder plugin for WordPress. With FluentAffiliate, you can easily manage affiliate commissions based on product sales, discounts, renewals, and upgrades.</p><p>This guide will walk you through the process of integrating EasyCart with FluentAffiliate step by step.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>First, <strong>install and activate</strong> the EasyCart plugin on your WordPress website. This will set up your online store and shopping cart functionality.</p></div><h2 id="connecting-easycart-with-fluentaffiliate" tabindex="-1">Connecting EasyCart with FluentAffiliate <a class="header-anchor" href="#connecting-easycart-with-fluentaffiliate" aria-label="Permalink to &quot;Connecting EasyCart with FluentAffiliate&quot;">​</a></h2><p>Once EasyCart is active, head over to the <strong>FluentAffiliate Dashboard</strong>. In the top menu, click on <strong>Settings</strong>, and from the left sidebar, select the <strong>Integration Settings</strong> option.</p><p>Inside the Integration Settings page, you&#39;ll find a list of available integrations. Locate <strong>EasyCart</strong> in this list. To enable the integration, simply click the <strong>toggle</strong> button next to EasyCart.</p><p>Your <strong>EasyCart</strong> integration with <strong>FluentAffiliate</strong> is now active, allowing affiliates to earn referral commissions on EasyCart product sales.</p><p>In the <strong>Manage</strong> section, you&#39;ll find additional settings to customize how affiliate commissions work with your EasyCart products.</p>',9)),e("p",null,[n(a,{src:"/guide/public/images/integrations/easycart/easycart-setup-options.webp",alt:"Integration Settings"})]),t[1]||(t[1]=o('<h2 id="configure-the-easycart-settings-in-fluentaffiliate" tabindex="-1">Configure the EasyCart Settings in FluentAffiliate <a class="header-anchor" href="#configure-the-easycart-settings-in-fluentaffiliate" aria-label="Permalink to &quot;Configure the EasyCart Settings in FluentAffiliate&quot;">​</a></h2><p>A pop-up will appear where you&#39;ll find <strong>two</strong> important <strong>settings</strong> to manage how affiliate commissions are handled. You can enable or disable these options based on your preferences:</p><p><strong>Disable commission on renewal</strong>: If you check this option, FluentAffiliate will disable affiliate commissions for all <strong>product renewals</strong>. Affiliates will not earn commissions when customers renew their purchases.</p><p><strong>Disable commission on upgrade</strong>: If you enable this option, all product <strong>upgrade commissions</strong> will be turned off for affiliates. This means no commissions will be given when customers upgrade from one product plan to another.</p><p>Once you&#39;ve selected the settings, click the <strong>Update</strong> button to save your changes.</p>',5)),e("p",null,[n(a,{src:"/guide/public/images/integrations/easycart/easycart-settings-configuration.webp",alt:"Configure EasyCart Settings"})]),t[2]||(t[2]=o('<h2 id="generate-an-affiliate-link" tabindex="-1">Generate an Affiliate Link <a class="header-anchor" href="#generate-an-affiliate-link" aria-label="Permalink to &quot;Generate an Affiliate Link&quot;">​</a></h2><p>After you&#39;ve finished configuring the EasyCart product settings, the next step is to log in to your <strong>Affiliate Area</strong> provided by FluentAffiliate. In the <strong>Affiliate Links</strong> section, paste the <strong>URL</strong> of the product page you want to promote. FluentAffiliate will automatically generate a <strong>unique affiliate link</strong> for you.</p><p>Once your link is ready, <strong>copy</strong> the affiliate link and share it wherever you like — on social media, emails, blogs, or directly with your audience.</p>',3)),e("p",null,[n(a,{src:"/guide/public/images/integrations/easycart/affiliate-link-generation.webp",alt:"Affiliate Link"})]),t[3]||(t[3]=e("p",null,[i("If someone purchases the product using your affiliate link, you'll earn a "),e("strong",null,"commission"),i(" based on the settings you've configured.")],-1)),e("p",null,[n(a,{src:"/guide/public/images/integrations/easycart/referral-overview.webp",alt:"Referral"})]),t[4]||(t[4]=e("h3",{id:"troubleshooting-common-issues",tabindex:"-1"},[i("Troubleshooting Common Issues "),e("a",{class:"header-anchor",href:"#troubleshooting-common-issues","aria-label":'Permalink to "Troubleshooting Common Issues"'},"​")],-1)),t[5]||(t[5]=e("p",null,"Here are solutions to common issues you might encounter:",-1)),t[6]||(t[6]=e("ul",null,[e("li",null,[e("strong",null,"Integration Toggle Not Visible:"),i(" Ensure both EasyCart and FluentAffiliate are activated. If the issue continues, deactivate and reactivate both plugins, and then check again.")]),e("li",null,[e("strong",null,"Commissions Not Tracking:"),i(" Verify that the integration toggle is enabled. You can test your affiliate link to ensure it working.")])],-1)),t[7]||(t[7]=e("p",null,"And that's it! This is an easy process how to integrate EasyCart with FluentAffiliate and start earning commissions.",-1))])}const w=s(u,[["render",f]]);export{b as __pageData,w as default};
